<script setup>
import {ref} from 'vue';const emit=defineEmits(['close','status']);const camera=ref('Not requested');const mic=ref('Not requested');const motion=ref('Simulator');const publish=()=>emit('status',{camera:camera.value,mic:mic.value,motion:motion.value});const request=async(kind)=>{try{const stream=await navigator.mediaDevices.getUserMedia(kind==='camera'?{video:{facingMode:'environment'},audio:false}:{audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});stream.getTracks().forEach(t=>t.stop());if(kind==='camera')camera.value='Granted · idle';else mic.value='Granted · idle';}catch{if(kind==='camera')camera.value='Restricted / unavailable';else mic.value='Restricted / unavailable'}publish()};const askMotion=async()=>{try{if(typeof DeviceMotionEvent!=='undefined'&&typeof DeviceMotionEvent.requestPermission==='function'){const res=await DeviceMotionEvent.requestPermission();motion.value=res==='granted'?'Granted · browser':'Restricted'}else motion.value='Browser sensor available or simulator'}catch{motion.value='Restricted'}publish()};
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal glass"><div class="modal-head"><div><div class="eyebrow">Device access</div><h2>Hardware permissions</h2><p class="small">Permissions are requested only when you press a control. Samples remain local unless you explicitly export or connect a backend.</p></div><button class="close" @click="emit('close')">×</button></div><div class="inner"><div class="control-row"><div><b>Rear camera</b><div class="small">Macro preview and color sampling</div></div><div class="split"><span class="badge">{{camera}}</span><button class="action" @click="request('camera')">Request</button></div></div><div class="control-row"><div><b>Microphone</b><div class="small">TMJ / toothbrush acoustic experiments</div></div><div class="split"><span class="badge">{{mic}}</span><button class="action" @click="request('mic')">Request</button></div></div><div class="control-row"><div><b>Motion sensors</b><div class="small">Brushing orientation, if supported</div></div><div class="split"><span class="badge">{{motion}}</span><button class="action" @click="askMotion">Check</button></div></div><div class="control-row"><div><b>Offline storage</b><div class="small">IndexedDB / local fallback</div></div><span class="badge">{{'indexedDB' in window?'AVAILABLE':'LOCAL STORAGE'}}</span></div></div><div class="notice" style="margin-top:14px">Camera screen illumination is not a 405 nm diagnostic light source; consumer phone cameras cannot provide clinical QLF measurements.</div></section></div></template>
